INSERT INTO `announcements` (`id`, `user_id`, `body`, `comments_restricted`, `created_at`, `updated_at`) VALUES
(1, 3, '📢 SCHEDULED WATER INTERRUPTION\n\nMaynilad will have a water interruption this Saturday from 9:00 AM to 4:00 PM. Please store enough water the night before. Salamat po sa pag-unawa!', 0, '2026-10-05 00:30:00', '2026-10-05 00:30:00'),
(2, 4474, 'Reminder: Rent is due on the 1st of every month. You have a 3-day grace period; after that, a one-time 10% late fee is added. Pay in cash at the admin office, or through our official GCash (0917 893 2970, Patricia Joy N.) or BDO account, then upload your proof of payment in the portal.', 0, '2026-09-30 00:30:00', '2026-09-30 00:30:00'),
(3, 3, 'Fire drill and building inspection next Wednesday, 3:00 PM. Attendance is required for all tenants who are in the building. Please review the evacuation plan posted on every floor (Rules and Regulations, item 12). Comments are turned off for this post.', 1, '2026-09-26 00:30:00', '2026-09-26 00:30:00');
INSERT INTO `announcement_comments` (`id`, `announcement_id`, `user_id`, `tenant_id`, `body`, `created_at`) VALUES
(1, 1, NULL, 1, 'Noted po, thank you sa heads up!', '2026-10-05 01:30:00'),
(2, 1, NULL, 7, 'Buong araw po ba walang tubig sa lahat ng floors?', '2026-10-05 03:30:00'),
(3, 1, 4474, NULL, 'Opo, lahat ng floors po. May drum ng tubig sa ground floor na pwede gamitin.', '2026-10-05 05:30:00'),
(4, 2, NULL, 8, 'Pwede po ba partial muna ngayong week?', '2026-09-30 01:30:00'),
(5, 2, 4475, NULL, 'Pwede po, pero may 10% late fee sa natitirang upa kung lumampas sa 3-day grace period.', '2026-09-30 03:30:00');
