(3, 'Ground Floor', 0.00, 0.00, 1, 'Lobby, receiving area and study hall. Solo fan rooms and 4-person AC rooms.', '2026-07-29 22:22:25', '2026-10-06 00:00:00'),
(11, 'Second Floor', 0.00, 0.00, 2, '4-person and 6-person air-conditioned rooms.', '2026-09-04 13:04:53', '2026-10-06 00:00:00'),
(12, 'Third Floor', 0.00, 0.00, 3, 'Air-conditioned rooms, including a 12-bed dorm room.', '2026-09-29 13:00:54', '2026-10-06 00:00:00'),
(13, 'Fourth Floor', 0.00, 0.00, 4, '6-person room and a 16-bed dorm room.', '2026-10-01 15:12:48', '2026-10-06 00:00:00'),
(14, 'Fifth Floor', 0.00, 0.00, 5, 'Large dorm room and a 4-person room with a view of the LRT line.', '2026-10-01 15:12:48', '2026-10-06 00:00:00');
INSERT INTO `inquiries` (`id`, `full_name`, `contact_number`, `email`, `room_id`, `message`, `reply_message`, `replied_at`, `replied_by`, `preferred_room_type`, `dpa_consent`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Aira Nicole Dimaculangan', '09174402167', 'aira.dimaculangan@gmail.com', 89, 'Hello po! May available pa po bang bedspace for female this November? Magkano po ang 6-person AC room?', NULL, NULL, NULL, 'Room with AC, 6 persons', 1, 'new', '2026-10-05 21:00:00', '2026-10-05 21:00:00'),
(2, 'Rhenz Adrian Pacheco', '09184410086', 'rhenz.pacheco@gmail.com', 16, 'Good day! Pwede po ba mag-ocular visit this Saturday? Working po ako sa Makati, looking for a solo room.', NULL, NULL, NULL, 'Solo fan room', 1, 'new', '2026-10-05 03:12:00', '2026-10-05 03:12:00'),
(3, 'Janella Marie Quiambao', '09274418005', 'janella.quiambao@gmail.com', NULL, 'Kasama na po ba ang WiFi at kuryente sa monthly rate?', 'Hi Janella! Opo, kasama na po ang tubig, kuryente at WiFi sa monthly rate. ₱4,200 per bed po ang 4-person AC room sa 2nd to 5th floor. Welcome po kayong mag-visit!', '2026-10-03 10:12:00', 4474, 'Room with AC, 4 persons', 1, 'contacted', '2026-10-03 05:12:00', '2026-10-03 10:12:00'),
(4, 'Luis Gabriel Soriano', '09394425924', 'luis.soriano@gmail.com', 91, 'Is there a curfew? I have night classes until 9 PM.', 'Hello Luis! Curfew is 11 PM to 4 AM, so 9 PM classes are no problem. If you ever need to come home later, just inform the office in advance. Feel free to apply online through our website.', '2026-10-01 12:12:00', 4474, 'Room with AC, 10–16 persons', 1, 'contacted', '2026-10-01 07:12:00', '2026-10-01 12:12:00'),
(5, 'Ryan Christopher Santiago', '09454433843', 'ryan.santiago@gmail.com', 19, 'Interested po ako sa Room 203, pwede po ba mag-apply online?', 'Yes po! Na-send na namin ang link. Paki-fill up lang po ang application form at pirmahan ang documents online.', '2026-09-29 14:12:00', 4474, 'Room with AC, 4 persons', 1, 'converted', '2026-09-29 09:12:00', '2026-09-29 14:12:00'),
(6, 'Mylene Castillo', '09564441762', 'mylene.castillo@gmail.com', NULL, 'Pwede po ba ang pets? May maliit po akong pusa.', 'Sorry po, bawal po ang pets sa dormitory (Rules and Regulations, item 11). Salamat sa interest!', '2026-09-24 16:12:00', 4474, NULL, 1, 'closed', '2026-09-24 11:12:00', '2026-09-24 16:12:00');
