INSERT INTO `partner_requests` (`id`, `owner_name`, `dorm_name`, `email`, `contact_number`, `city`, `bed_count`, `message`, `dpa_consent`, `status`, `notes`, `reply_message`, `replied_at`, `created_at`, `updated_at`) VALUES
(1, 'Maricel Santos', 'Casa Lorenzo Ladies Dormitory', 'maricel.santos@example.com', '09171234501', 'Sampaloc, Manila', 48, 'We currently track rent in a notebook and Excel. Interested in the online billing and the tenant portal. Can we see a demo on a weekend?', 1, 'new', NULL, NULL, NULL, '2026-10-05 04:38:00', '2026-10-05 04:38:00'),
(2, 'Ramon dela Cruz', 'Kalye Uno Student Residences', 'ramon.delacruz@example.com', '09281234502', 'Sta. Mesa, Manila', 72, 'Near PUP like Pureza Station. Mostly interested in the VR tours since many of our applicants are from the provinces.', 1, 'new', NULL, NULL, NULL, '2026-10-04 01:42:00', '2026-10-04 01:42:00'),
(3, 'Josephine Villanueva', 'JV Boarding House', 'jv.boardinghouse@example.com', '09391234503', 'Diliman, Quezon City', 24, 'Small boarding house, 6 rooms. Is this okay for a small place?', 1, 'contacted', NULL, NULL, NULL, '2026-09-30 03:19:00', '2026-09-30 03:19:00'),
(4, 'Antonio Reyes', 'Espana Heights Dormitory', 'areyes.espanaheights@example.com', '09451234504', 'Sampaloc, Manila', 120, 'We have 3 floors and a caretaker per floor. Need separate admin accounts with different access.', 1, 'demo_scheduled', NULL, NULL, NULL, '2026-09-27 00:10:00', '2026-09-27 00:10:00'),
(5, 'Grace Mendoza', 'Taft Commons Dorm', 'grace.mendoza@example.com', '09561234505', 'Malate, Manila', 60, 'Looking for a system before the next semester intake.', 1, 'onboarded', NULL, NULL, NULL, '2026-09-15 03:00:00', '2026-09-15 03:00:00'),
(6, 'Edgar Bautista', 'Bautista Bedspace', 'edgar.bautista@example.com', '09671234506', 'Pasig City', 8, 'Just checking the price.', 1, 'declined', NULL, NULL, NULL, '2026-09-21 00:47:00', '2026-09-21 00:47:00');
INSERT INTO `partner_request_notes` (`id`, `partner_request_id`, `user_id`, `body`, `created_at`, `updated_at`) VALUES
(1, 1, 3872, 'Tried calling, no answer. Will try again tomorrow morning.', '2026-10-05 08:05:00', '2026-10-05 08:05:00'),
(2, 3, 3872, 'Called. Owner manages the place alone; mainly needs billing reminders and a record of who has paid.', '2026-10-01 02:05:00', '2026-10-01 02:05:00'),
(3, 3, 3872, 'Sent pricing and the tenant manual by email.', '2026-10-01 07:12:00', '2026-10-01 07:12:00'),
(4, 3, 3872, 'Owner replied: will decide after talking to her sister, who co-owns the building. Follow up next week.', '2026-10-04 01:19:00', '2026-10-04 01:19:00'),
(5, 4, 3872, 'Called. Three caretakers, one per floor; each should only handle tickets and payments.', '2026-09-28 03:05:00', '2026-09-28 03:05:00'),
(6, 4, 3872, 'Demo set for Saturday 10 AM via Google Meet.', '2026-09-29 06:12:00', '2026-09-29 06:12:00'),
(7, 4, 3872, 'For the demo: show Admin Privileges and the automatic assignment of emergency tickets.', '2026-09-29 06:19:00', '2026-09-29 06:19:00'),
(8, 5, 3872, 'Called. Wants to go live before the next semester intake.', '2026-09-16 01:05:00', '2026-09-16 01:05:00'),
(9, 5, 3872, 'Demo done. Owner liked the move-in payment flow and the delinquency reminders.', '2026-09-18 05:12:00', '2026-09-18 05:12:00'),
(10, 5, 3872, 'Rooms, rates and house rules set up. Admin accounts created.', '2026-09-23 02:19:00', '2026-09-23 02:19:00'),
(11, 5, 3872, 'Waiting for their 360 room photos before going live.', '2026-09-27 08:26:00', '2026-09-27 08:26:00'),
(12, 6, 3872, 'Called. Only 8 beds; the owner prefers to keep collecting through GCash chat.', '2026-09-22 09:05:00', '2026-09-22 09:05:00'),
(13, 6, 3872, 'Not a fit for now. Follow up next year.', '2026-09-23 02:12:00', '2026-09-23 02:12:00');
