INSERT INTO `reviews` (`id`, `tenant_id`, `rating`, `comment`, `photos`, `is_approved`, `status`, `flag_reasons`, `moderated_by`, `moderated_at`, `moderation_note`, `created_at`, `updated_at`) VALUES
(1, 1, 5, 'Sobrang linis ng rooms and very accommodating ang staff. Five minutes lang lakad papuntang PUP. Highly recommended!', '[\"reviews\\/demo\\/review-photo-1.jpg\",\"reviews\\/demo\\/review-photo-2.jpg\"]', 1, 'published', NULL, NULL, NULL, NULL, '2026-09-29 16:00:00', '2026-09-29 16:00:00'),
(2, 5, 4, 'Maayos ang WiFi at tahimik sa gabi. Minsan lang medyo mahina ang tubig sa umaga pero agad naman inaayos.', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-25 16:00:00', '2026-09-25 16:00:00'),
(3, 11, 5, 'Almost a year na ako dito. Safe, may curfew, at mabait si Ma\'am Tess. Perfect para sa mga nurse na shifting.', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-19 16:00:00', '2026-09-19 16:00:00'),
(4, 15, 3, 'Okay naman overall. Sana lang may kitchen na pwedeng gamitin kasi bawal magluto sa room.', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-15 16:00:00', '2026-09-15 16:00:00'),
(5, 18, 4, 'Good value for money. Malinis ang CR at laging may tubig. Medyo strict sa visitors pero understandable.', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-12 16:00:00', '2026-09-12 16:00:00'),
(6, 23, 5, 'Nag-move out na ako kasi lumipat ang work ko, pero sobrang saya ng stay ko dito. Salamat Pureza Station!', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-27 16:00:00', '2026-09-27 16:00:00'),
(7, 25, 5, 'Ang ganda ng study hall sa baba, dito ako nagre-review lagi. Mabilis din sumagot ang admin sa tickets.', NULL, 1, 'published', NULL, NULL, NULL, NULL, '2026-09-25 16:00:00', '2026-09-25 16:00:00'),
(8, 12, 1, 'Mas mura sa amin! Visit www.cheapdorms-manila.com for promo, message 0917-000-0000', NULL, 0, 'hidden', '[\"Contains a link\",\"Contains a phone number\"]', NULL, NULL, NULL, '2026-10-02 16:00:00', '2026-10-02 16:00:00'),
(9, 17, 2, 'Pangit ugali ng roommate ko, [name removed] sobrang ingay.', NULL, 0, 'removed', NULL, 4474, '2026-09-29 16:00:00', 'Removed: names another tenant. Concern was redirected to a support ticket instead.', '2026-09-28 16:00:00', '2026-09-29 16:00:00');
